sksl:
uniform shader image;
uniform float2 size;
uniform float time;
uniform shader blurred;
uniform float blur;
uniform float thickness;
uniform float detail;
uniform float distortion;
layout(color) uniform half4 color;
layout(color) uniform half4 glowColor;
uniform float alpha;
uniform float glow;
uniform float seed;
uniform float evolution;
uniform float fill;
uniform float maskStrength;
uniform float maskEvolution;
uniform float maskScale;
uniform float maskSeed;
layout(color) uniform half4 maskColor;
uniform float contours;
uniform float count;
uniform float phase;
uniform float contourAngle;
float hash13(float3 p) {
    p = fract(p * 0.1031);
    p += dot(p, p.zyx + 31.32);
    return fract((p.x + p.y) * p.z);
}
float vnoise(float3 p) {
    float3 i = floor(p);
    float3 f = fract(p);
    f = f * f * (3.0 - 2.0 * f);
    float a = mix(hash13(i), hash13(i + float3(1, 0, 0)), f.x);
    float b = mix(hash13(i + float3(0, 1, 0)), hash13(i + float3(1, 1, 0)), f.x);
    float c = mix(hash13(i + float3(0, 0, 1)), hash13(i + float3(1, 0, 1)), f.x);
    float d = mix(hash13(i + float3(0, 1, 1)), hash13(i + float3(1, 1, 1)), f.x);
    return mix(mix(a, b, f.y), mix(c, d, f.y), f.z);
}
float fbm(float3 p, float octaves) {
    float sum = 0.0;
    float amp = 0.5;
    float norm = 0.0;
    for (int i = 0; i < 6; i++) {
        if (float(i) >= octaves) break;
        sum += amp * vnoise(p);
        norm += amp;
        amp *= 0.55;
        p = float3(p.xy * 2.07 + 13.1, p.z * 1.5 + 2.3);
    }
    return norm > 0.0 ? sum / norm : 0.5;
}
float field(float2 p) { return float(blurred.eval(p).a); }
half4 main(float2 coord) {
    half4 src = image.eval(coord);
    float reach = max(blur, 1.0);
    float octaves = clamp(2.0 + detail * 0.5, 1.0, 6.0);
    float3 q = float3(coord * (1.0 + detail * 0.25) / (reach * 0.8) + seed * float2(41.3, 17.9), evolution * 0.1);
    float2 warp = float2(fbm(q, octaves), fbm(q + float3(19.1, 7.3, 3.7), octaves)) - 0.5;
    float2 p = coord + warp * distortion * reach * 0.7;
    float b = field(p);
    float e = 1.0;
    float2 g = float2(field(p + float2(e, 0.0)) - field(p - float2(e, 0.0)), field(p + float2(0.0, e)) - field(p - float2(0.0, e))) / (2.0 * e);
    float level = mix(0.5, 0.06, blur > 0.0 ? 1.0 : 0.0);
    float dist = abs(b - level) / max(length(g), 0.0005);
    float width = mix(0.6, reach * 0.12, clamp(thickness, 0.0, 1.0));
    float core = (1.0 - smoothstep(width * 0.5, width * 0.5 + 1.0, dist)) * clamp(alpha, 0.0, 1.0);
    float halo = exp(-dist / max(width * 2.0, 2.0)) * clamp(glow, 0.0, 1.0);
    float3 rgb = float3(color.rgb) * core * float(color.a) + float3(glowColor.rgb) * halo * float(glowColor.a);
    float a = clamp(core * float(color.a) + halo * float(glowColor.a), 0.0, 1.0);
    if (maskStrength > 0.0) {
        float mn = vnoise(float3(coord / (40.0 * max(maskScale, 0.01)) + maskSeed * float2(23.1, 51.7), maskEvolution * 0.2));
        float keep = smoothstep(maskStrength - 0.12, maskStrength + 0.12, mn);
        float edge = keep * (1.0 - keep) * 4.0;
        rgb = mix(rgb, float3(maskColor.rgb) * a, edge);
        rgb *= keep;
        a *= keep;
    }
    half4 body = src * half(clamp(fill, 0.0, 1.0));
    if (contours > 0.5 && src.a > 0.0) {
        float ca = radians(contourAngle);
        float2 dir = float2(-sin(ca), cos(ca));
        float h = dot(coord - size * 0.5, dir) / max(length(size), 1.0) * count + phase + (1.0 - field(coord)) * 2.0;
        float line = 1.0 - smoothstep(0.0, 0.12, abs(fract(h) - 0.5) * 2.0 - 0.76);
        float la = line * float(src.a) * clamp(alpha, 0.0, 1.0);
        body = half4(half3(float3(body.rgb) * (1.0 - la) + float3(color.rgb) * la), max(body.a, half(la)));
    }
    half4 edgeLight = half4(half3(clamp(rgb, 0.0, 1.0)), half(a));
    return half4(min(body.rgb + edgeLight.rgb, half3(1.0)), body.a + edgeLight.a * (1.0 - body.a));
}
